using System;
using System.Collections.Generic;
using UnityEngine;

namespace SixtyOne.World
{
    /// <summary>
    /// Prop name → sprite (bottom-centre pivot, PPU set so each prop lands at its target height). The scene builder
    /// uses the sprite when a prop name is mapped and the coloured block otherwise. Generated by SixtyOne > Art >
    /// Import Prop Art.
    /// </summary>
    [CreateAssetMenu(menuName = "SixtyOne/Prop Art Set", fileName = "PropArtSet")]
    public sealed class PropArtSet : ScriptableObject
    {
        /// <summary>One prop name and its sprite.</summary>
        [Serializable]
        public sealed class Entry
        {
            [Tooltip("Prop name as used by BuildingLayout (Table, Wardrobe, Stove...).")]
            public string Name;

            public Sprite Sprite;
        }

        [Tooltip("Prop name → sprite.")]
        [SerializeField] private List<Entry> entries = new List<Entry>();

        [Tooltip("Chandelier frames: 0..n-2 swing during a quake, the last one lies fallen on the floor.")]
        [SerializeField] private Sprite[] chandelierFrames = new Sprite[0];

        [Tooltip("Debris variants (enkaz 1 / enkaz 2).")]
        [SerializeField] private Sprite[] debris = new Sprite[0];

        public IReadOnlyList<Entry> Entries => entries;
        public Sprite[] ChandelierFrames => chandelierFrames;
        public Sprite[] Debris => debris;

        /// <summary>Sprite for a prop name, or null (the builder keeps the coloured block).</summary>
        public Sprite Find(string propName)
        {
            if (string.IsNullOrEmpty(propName)) return null;
            foreach (Entry e in entries)
            {
                if (e != null && e.Sprite != null && string.Equals(e.Name, propName, StringComparison.OrdinalIgnoreCase)) return e.Sprite;
            }

            return null;
        }

        /// <summary>Authoring helper for the importer.</summary>
        public void Configure(IEnumerable<Entry> mapped, Sprite[] chandelier, Sprite[] debrisSprites)
        {
            entries = mapped != null ? new List<Entry>(mapped) : new List<Entry>();
            chandelierFrames = chandelier ?? new Sprite[0];
            debris = debrisSprites ?? new Sprite[0];
        }
    }
}
